//! The tool definitions `apps/server` advertises, one compact JSON line per tool, generated by
//! `tools/gen-tools.mjs`. `tools/list` splices the bytes unparsed; a call parses only its own
//! tool's line, to check the arguments against the advertised input schema.

use serde_json::{Map, Value};

const CATALOG: &str = include_str!("catalog.jsonl");

pub(crate) fn lines() -> impl Iterator<Item = &'static str> {
    CATALOG.lines().filter(|line| !line.is_empty())
}

/// Every tool's name, in catalog order.
#[cfg(test)]
pub(crate) fn names() -> impl Iterator<Item = &'static str> {
    lines().filter_map(|line| {
        line.strip_prefix("{\"name\":\"")
            .and_then(|rest| rest.split_once('"'))
            .map(|(name, _)| name)
    })
}

/// The `tools/list` result body.
pub(crate) fn list_result() -> String {
    let mut out = String::with_capacity(CATALOG.len() + 16);
    out.push_str("{\"tools\":[");
    for (i, line) in lines().enumerate() {
        if i > 0 {
            out.push(',');
        }
        out.push_str(line);
    }
    out.push_str("]}");
    out
}

/// One tool's definition, parsed, and its argument names in advertised order (serde_json
/// sorts object keys; error texts list them as TS does).
pub(crate) fn tool(name: &str) -> Option<(Value, Vec<String>)> {
    let prefix = format!("{{\"name\":{},", Value::String(name.to_owned()));
    let line = lines().find(|line| line.starts_with(&prefix))?;
    let tool = serde_json::from_str(line).ok()?;
    Some((tool, argument_order(line)))
}

/// The keys of `inputSchema.properties`, as written in the line.
fn argument_order(line: &str) -> Vec<String> {
    const START: &str = "\"inputSchema\":{\"type\":\"object\",\"properties\":{";
    let Some(at) = line.find(START) else {
        return Vec::new();
    };
    let mut keys = Vec::new();
    let mut depth = 0usize;
    let mut chars = line[at + START.len()..].char_indices().peekable();
    let rest = &line[at + START.len()..];
    while let Some((i, c)) = chars.next() {
        match c {
            '"' => {
                let start = i + 1;
                let mut end = start;
                while let Some((j, c)) = chars.next() {
                    if c == '\\' {
                        chars.next();
                    } else if c == '"' {
                        end = j;
                        break;
                    }
                }
                let is_key = depth == 0 && chars.peek().is_some_and(|(_, c)| *c == ':');
                if is_key
                    && let Ok(Value::String(key)) =
                        serde_json::from_str(rest.get(start - 1..=end).unwrap_or_default())
                {
                    keys.push(key);
                }
            }
            '{' | '[' => depth += 1,
            '}' | ']' if depth == 0 => break,
            '}' | ']' => depth -= 1,
            _ => {}
        }
    }
    keys
}

const MAX_NAMED_ARGUMENTS: usize = 5;

/// Checks `arguments` as `decodeAsAdvertised` does in TS: `null` for an optional field counts
/// as omitted (and is removed), an argument the schema does not list is refused by name, and
/// required fields and simple types are checked. Nested objects stay lenient, as in TS.
/// The error text follows Effect's where an agent relies on it (unknown and missing keys).
pub(crate) fn check_arguments(
    schema: &Value,
    order: &[String],
    arguments: &mut Map<String, Value>,
) -> Result<(), String> {
    let empty = Map::new();
    let properties = schema["properties"].as_object().unwrap_or(&empty);
    let required: Vec<&str> = schema["required"]
        .as_array()
        .map(|r| r.iter().filter_map(Value::as_str).collect())
        .unwrap_or_default();
    let unknown: Vec<&String> = arguments
        .keys()
        .filter(|key| !properties.contains_key(*key))
        .collect();
    if !unknown.is_empty() {
        let named: Vec<String> = unknown
            .iter()
            .take(MAX_NAMED_ARGUMENTS)
            .map(|key| Value::String(key.chars().take(64).collect()).to_string())
            .collect();
        let more = if unknown.len() > named.len() {
            format!(" and {} more", unknown.len() - named.len())
        } else {
            String::new()
        };
        let accepted = if properties.is_empty() {
            "none".to_owned()
        } else {
            order.join(", ")
        };
        return Err(format!(
            "Unknown argument{} {}{more}. Accepted arguments: {accepted}.",
            if unknown.len() == 1 { "" } else { "s" },
            named.join(", ")
        ));
    }
    arguments.retain(|key, value| !value.is_null() || required.contains(&key.as_str()));
    for key in &required {
        if !arguments.contains_key(*key) {
            return Err(format!("Missing key\n  at [\"{key}\"]"));
        }
    }
    for (key, value) in arguments.iter() {
        if let Some(problem) = type_problem(&properties[key], value) {
            return Err(format!("{problem}\n  at [\"{key}\"]"));
        }
    }
    Ok(())
}

fn type_problem(schema: &Value, value: &Value) -> Option<String> {
    if let Some(options) = schema["anyOf"].as_array() {
        return options
            .iter()
            .all(|option| type_problem(option, value).is_some())
            .then(|| format!("Expected a value matching the schema, got {value}"));
    }
    if let Some(allowed) = schema["enum"].as_array()
        && !allowed.contains(value)
    {
        let names: Vec<String> = allowed.iter().map(Value::to_string).collect();
        return Some(format!("Expected {}, got {value}", names.join(" | ")));
    }
    let fits = match schema["type"].as_str() {
        Some("string") => value.as_str().is_some_and(|text| {
            schema["maxLength"]
                .as_u64()
                .is_none_or(|max| text.chars().count() as u64 <= max)
        }),
        Some("integer") => value.as_i64().is_some_and(|n| in_range(schema, n as f64)),
        Some("number") => value.as_f64().is_some_and(|n| in_range(schema, n)),
        Some("boolean") => value.is_boolean(),
        Some("array") => value.as_array().is_some_and(|items| {
            schema["maxItems"]
                .as_u64()
                .is_none_or(|max| items.len() as u64 <= max)
        }),
        Some("object") => value.is_object(),
        _ => true,
    };
    (!fits).then(|| match schema["type"].as_str() {
        Some(kind) => format!("Expected {kind}, got {value}"),
        None => format!("Unexpected {value}"),
    })
}

fn in_range(schema: &Value, n: f64) -> bool {
    schema["minimum"].as_f64().is_none_or(|min| n >= min)
        && schema["maximum"].as_f64().is_none_or(|max| n <= max)
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn every_line_parses_and_names_itself() {
        for line in lines() {
            let tool: Value = serde_json::from_str(line).unwrap();
            assert_eq!(tool["inputSchema"]["type"], "object");
            assert!(names().any(|n| n == tool["name"]));
        }
        let list: Value = serde_json::from_str(&list_result()).unwrap();
        assert_eq!(list["tools"].as_array().unwrap().len(), names().count());
    }

    /// The catalog is byte for byte what a live TypeScript server listed
    /// (`fixtures/ts-tools-list.json`, a real `tools/list` reply).
    #[test]
    fn matches_the_typescript_servers_tools_list() {
        let dump: Value =
            serde_json::from_str(include_str!("../fixtures/ts-tools-list.json")).unwrap();
        let live = dump["result"]["tools"].as_array().unwrap();
        for line in lines() {
            let ours: Value = serde_json::from_str(line).unwrap();
            let theirs = live
                .iter()
                .find(|t| t["name"] == ours["name"])
                .unwrap_or_else(|| panic!("{} is not in the TS dump", ours["name"]));
            assert_eq!(&ours, theirs, "{}", ours["name"]);
        }
    }

    #[test]
    fn checks_arguments_like_the_typescript_decoder() {
        let (list, order) = tool("t3_thread_list").unwrap();
        let schema = list["inputSchema"].clone();
        let mut args = json!({"bogus": 1}).as_object().unwrap().clone();
        assert_eq!(
            check_arguments(&schema, &order, &mut args).unwrap_err(),
            "Unknown argument \"bogus\". Accepted arguments: environmentId, projectId, allProjects, statuses, titleContains, settled, snoozed, includeSubagents, cursor, limit."
        );
        let (wait, wait_order) = tool("t3_thread_wait").unwrap();
        let wait = wait["inputSchema"].clone();
        let mut args = Map::new();
        assert_eq!(
            check_arguments(&wait, &wait_order, &mut args).unwrap_err(),
            "Missing key\n  at [\"threadId\"]"
        );
        let mut args = json!({"threadId": "t", "runId": null})
            .as_object()
            .unwrap()
            .clone();
        check_arguments(&wait, &wait_order, &mut args).unwrap();
        assert!(!args.contains_key("runId"));
        let mut args = json!({"threadId": 5}).as_object().unwrap().clone();
        assert!(check_arguments(&wait, &wait_order, &mut args).is_err());
        let mut args = json!({"limit": 101}).as_object().unwrap().clone();
        assert!(check_arguments(&schema, &order, &mut args).is_err());
        let mut args = json!({"statuses": ["running"]})
            .as_object()
            .unwrap()
            .clone();
        check_arguments(&schema, &order, &mut args).unwrap();
    }
}
